import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import { z } from "zod";
import { readFile, writeFile, rename, mkdir } from "node:fs/promises";
import path from "node:path";
import { homedir } from "node:os";
import { randomUUID } from "node:crypto";
import { renderCustom, markHtml, esc, clip } from "./widgetKit.ts";

const server = new McpServer({ name: "labpilot-voice", version: "1.6.1" });
const ACCENT = "#3987e5";
const EXPERIMENT_ID = "EXP-042" as const;
const EXPERIMENT_TITLE = "Inulin Bacterial Growth Experiment";
const SAMPLE_ORDER = ["A", "B", "C", "D"] as const;
const DUPLICATE_WINDOW_MS = 8000;
const SAMPLE_META: Record<string, { condition: string; treatment?: string; concentration?: number; concentrationUnit?: string }> = {
  A: { condition: "Control" },
  B: { condition: "0.5% Inulin", treatment: "Inulin", concentration: 0.5, concentrationUnit: "%" },
  C: { condition: "1% Inulin", treatment: "Inulin", concentration: 1, concentrationUnit: "%" },
  D: { condition: "2% Inulin", treatment: "Inulin", concentration: 2, concentrationUnit: "%" },
};

type VoiceState = "READY" | "LISTENING" | "PROCESSING" | "RECORDED" | "NEEDS CLARIFICATION" | "COMPLETE";
type Observation = { id: string; experimentId: typeof EXPERIMENT_ID; sampleId: string; condition?: string; treatment?: string; concentration?: number; concentrationUnit?: string; measurementType: string; value: number; measurementUnit?: string; inputSource: "voice"; rawTranscript: string; timestamp: string };
type Session = { active: boolean; startedAt?: string; completedAt?: string };
type Database = { experimentId: typeof EXPERIMENT_ID; title: string; observations: Observation[]; session: Session };

const DATA_FILE = path.join(homedir(), "Library", "Application Support", "LabPilot Voice", "labpilot-session.json");
const API_URL = (process.env.LABPILOT_API_URL || "https://labpilot-voice.leah-1314.chatgpt.site/api/experiment").replace(/\/$/, "");
const API_TOKEN = process.env.LABPILOT_API_TOKEN;
const SITES_ACCESS_TOKEN = process.env.LABPILOT_SITES_ACCESS_TOKEN;
type RemoteMeasurement = { id: string; sampleId: string; condition: string; treatment: string | null; concentration: number | null; concentrationUnit: string | null; measurementType: string; value: number; unit: string | null; inputSource: "manual" | "voice" | "api"; createdAt: string };
type RemoteSnapshot = { experiment: { title: string }; measurements: RemoteMeasurement[] };
let mutationQueue: Promise<void> = Promise.resolve();
async function serialized<T>(fn: () => Promise<T>): Promise<T> { const run = mutationQueue.then(fn, fn); mutationQueue = run.then(() => undefined, () => undefined); return run; }
function authHeaders() { if (!API_TOKEN) throw new Error("LABPILOT_API_TOKEN is not configured in VoiceOS preferences."); if (!SITES_ACCESS_TOKEN) throw new Error("LABPILOT_SITES_ACCESS_TOKEN is not configured in VoiceOS preferences."); return { authorization: `Bearer ${API_TOKEN}`, "OAI-Sites-Authorization": `Bearer ${SITES_ACCESS_TOKEN}`, "content-type": "application/json" }; }
async function api(action?: Record<string, unknown>): Promise<RemoteSnapshot> {
  const result = await fetch(API_URL, { method: action ? "POST" : "GET", headers: authHeaders(), body: action ? JSON.stringify(action) : undefined });
  const data = await result.json() as RemoteSnapshot & { error?: string };
  if (!result.ok) throw new Error(data.error || `LabPilot API returned ${result.status}.`);
  return data;
}
const fromRemote = (item: RemoteMeasurement): Observation => ({ id: item.id, experimentId: EXPERIMENT_ID, sampleId: item.sampleId, condition: item.condition, treatment: item.treatment || undefined, concentration: item.concentration ?? undefined, concentrationUnit: item.concentrationUnit || undefined, measurementType: item.measurementType, value: item.value, measurementUnit: item.unit || undefined, inputSource: "voice", rawTranscript: "", timestamp: item.createdAt });
async function readSession(): Promise<Session> {
  await mkdir(path.dirname(DATA_FILE), { recursive: true });
  try {
    const raw = JSON.parse(await readFile(DATA_FILE, "utf8"));
    return raw.session && typeof raw.session === "object" ? { active: Boolean(raw.session.active), startedAt: typeof raw.session.startedAt === "string" ? raw.session.startedAt : undefined, completedAt: typeof raw.session.completedAt === "string" ? raw.session.completedAt : undefined } : { active: false };
  } catch (error: any) {
    if (error?.code !== "ENOENT") throw error;
    return { active: false };
  }
}
async function writeSession(session: Session) { await mkdir(path.dirname(DATA_FILE), { recursive: true }); const temp = `${DATA_FILE}.${randomUUID()}.tmp`; await writeFile(temp, JSON.stringify({ session }, null, 2), "utf8"); await rename(temp, DATA_FILE); }
async function load(): Promise<Database> { const [snapshot, session] = await Promise.all([api(), readSession()]); return { experimentId: EXPERIMENT_ID, title: snapshot.experiment.title || EXPERIMENT_TITLE, observations: snapshot.measurements.map(fromRemote), session }; }
async function save(db: Database) {
  const before = await api();
  const previous = before.measurements.map(fromRemote);
  const previousById = new Map(previous.map((item) => [item.id, item]));
  const nextById = new Map(db.observations.map((item) => [item.id, item]));
  const removed = previous.find((item) => !nextById.has(item.id));
  const added = db.observations.find((item) => !previousById.has(item.id));
  const corrected = db.observations.find((item) => previousById.has(item.id) && previousById.get(item.id)!.value !== item.value);
  if ([removed, added, corrected].filter(Boolean).length > 1) throw new Error("Only one VoiceOS measurement mutation can be saved at a time.");
  if (removed) await api({ action: "remove", measurementId: removed.id });
  if (corrected) await api({ action: "correct", measurementId: corrected.id, value: corrected.value });
  if (added) await api({ action: "record", input: { experimentId: "exp-042", sampleId: added.sampleId, condition: added.condition || "Voice observation", organism: "Bifidobacterium", treatment: added.treatment || null, concentration: added.concentration ?? null, concentrationUnit: added.concentrationUnit || null, measurementType: added.measurementType, value: added.value, unit: added.measurementUnit || null, inputSource: "voice" } });
  await writeSession(db.session);
}

const formatNumber = (value: number) => new Intl.NumberFormat("en-US", { maximumFractionDigits: 4 }).format(value);
const normalizeSample = (value: string) => value.replace(/^sample\s+/i, "").trim().toUpperCase();
const conditionLabel = (o: Partial<Observation>) => o.condition || [o.concentration === undefined ? "" : `${formatNumber(o.concentration)}${o.concentrationUnit || ""}`, o.treatment].filter(Boolean).join(" ") || "No condition";
const readingLabel = (o: Partial<Observation>) => `${o.measurementType || "Measurement"} ${o.value === undefined ? "—" : formatNumber(o.value)}${o.measurementUnit ? ` ${o.measurementUnit}` : ""}`;
function response(data: any, card: { html: string; height: number }) { return { content: [{ type: "text" as const, text: JSON.stringify({ ...data, _voiceos_glance: { blocks: [{ type: "widget", html: card.html, height: card.height }] } }) }] }; }

const BASE_CSS = `.lp{font:13px/1.35 -apple-system,BlinkMacSystemFont,"SF Pro Text",sans-serif;color:var(--ink-1);font-variant-numeric:tabular-nums;min-width:0}.lp-head{display:grid;grid-template-columns:18px minmax(0,1fr) auto;align-items:center;gap:8px;padding:10px 14px 8px;border-bottom:1px solid var(--line)}.lp-brand{min-width:0}.lp-brand b{display:block;font-size:10px;letter-spacing:.08em;text-transform:uppercase}.lp-brand span{display:block;font-size:11.5px;color:var(--ink-2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.lp-id{font-size:10px;font-weight:750;color:var(--accent);letter-spacing:.04em}`;
function header() { return `<header class="lp-head">${markHtml()}<div class="lp-brand"><b>LabPilot Voice</b><span>${esc(EXPERIMENT_TITLE)}</span></div><strong class="lp-id">${EXPERIMENT_ID}</strong></header>`; }
function errorCard(title: string, message: string, draft?: Partial<Observation>) {
  const css = BASE_CSS + `.err{padding:18px 14px 20px}.err label{font-size:10px;font-weight:750;letter-spacing:.08em;color:var(--bad)}.err h2{font-size:21px;line-height:1.12;margin-top:5px}.err p{font-size:12px;color:var(--ink-3);margin-top:7px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.draft{margin-top:12px;padding-top:9px;border-top:1px solid var(--line);font-size:11px;color:var(--ink-2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}`;
  return renderCustom({ accent: ACCENT, css, body: `<div class="lp">${header()}<section class="err"><label>LABPILOT UNAVAILABLE</label><h2>${esc(clip(title, 54))}</h2><p>${esc(clip(message, 180))}</p>${draft?.measurementType ? `<div class="draft">Draft preserved · ${esc(readingLabel(draft))}</div>` : ""}</section></div>`, height: draft?.measurementType ? 190 : 166 });
}
function latestOD(observations: Observation[]) { const latest = new Map<string, Observation>(); for (const o of observations) if (o.measurementType.toUpperCase() === "OD600" && Number.isFinite(o.value)) latest.set(normalizeSample(o.sampleId), o); return [...latest.values()]; }
function experimentProgress(observations: Observation[]) { const bySample = new Map(latestOD(observations).map((o) => [normalizeSample(o.sampleId), o])); const count = SAMPLE_ORDER.filter((s) => bySample.has(s)).length; const next = SAMPLE_ORDER.find((s) => !bySample.has(s)); return { bySample, count, next, complete: count === SAMPLE_ORDER.length }; }
function concentrationOf(o: Observation) { if (/control/i.test(o.condition || "")) return 0; if (Number.isFinite(o.concentration)) return o.concentration; const match = (o.condition || "").match(/(-?\d+(?:\.\d+)?)\s*%/); return match ? Number(match[1]) : undefined; }
function analyze(observations: Observation[]) {
  const points = latestOD(observations); if (!points.length) return { points, observation: "Waiting for the first OD600 measurement.", summary: "No OD600 measurements have been recorded." };
  const highest = points.reduce((a, b) => b.value > a.value ? b : a);
  const ordered = points.map((item) => ({ item, concentration: concentrationOf(item) })).filter((x): x is { item: Observation; concentration: number } => x.concentration !== undefined).sort((a, b) => a.concentration - b.concentration);
  if (ordered.length >= 2) { const first = ordered[0], last = ordered[ordered.length - 1]; const direction = Math.abs(last.item.value - first.item.value) < 0.005 ? "is steady" : last.item.value > first.item.value ? "rises" : "falls"; const firstName = first.concentration === 0 ? "Control" : conditionLabel(first.item); return { points, highest, observation: `Recorded OD600 ${direction}: ${firstName} ${formatNumber(first.item.value)} → ${conditionLabel(last.item)} ${formatNumber(last.item.value)}.`, summary: `OD600 ${direction} from ${formatNumber(first.item.value)} in ${firstName} to ${formatNumber(last.item.value)} at ${conditionLabel(last.item)}. Highest: Sample ${highest.sampleId}.` }; }
  return { points, highest, observation: `Sample ${points[0].sampleId} is the first recorded OD600 point.`, summary: `One OD600 reading is recorded: Sample ${points[0].sampleId} at ${formatNumber(points[0].value)}.` };
}
function completionMessage(observations: Observation[]) { const p = experimentProgress(observations); if (!p.complete) return undefined; const a = p.bySample.get("A")!, d = p.bySample.get("D")!; const direction = Math.abs(d.value - a.value) < 0.005 ? "is unchanged" : d.value > a.value ? "increases" : "decreases"; return `Experiment complete. Latest OD600 ${direction} from ${formatNumber(a.value)} in the control to ${formatNumber(d.value)} at 2% inulin.`; }

function dashboard(observations: Observation[], options: { state?: VoiceState; stateNote?: string; focus?: Partial<Observation>; highlight?: string[]; sessionActive?: boolean; transcript?: string } = {}) {
  const progress = experimentProgress(observations), analysis = analyze(observations), latest = options.focus || observations[observations.length - 1];
  const state: VoiceState = options.state || (progress.complete ? "COMPLETE" : options.sessionActive ? "LISTENING" : "READY");
  const nextSample = progress.next || "—"; const currentSample = latest?.sampleId && ["PROCESSING", "RECORDED", "NEEDS CLARIFICATION"].includes(state) ? normalizeSample(latest.sampleId) : nextSample;
  const defaultNote = state === "READY" ? "Tap or speak to begin" : state === "LISTENING" ? `Ready for Sample ${nextSample}` : state === "PROCESSING" ? "Structuring measurement…" : state === "RECORDED" ? `${latest?.sampleId ? `Sample ${normalizeSample(latest.sampleId)} · ` : ""}${latest?.measurementType || "Measurement"} ${latest?.value === undefined ? "" : formatNumber(latest.value)}` : state === "NEEDS CLARIFICATION" ? "One essential field is unclear" : "All four samples recorded";
  const stateNote = options.stateNote || defaultNote, highlight = new Set((options.highlight || []).map(normalizeSample));
  const values = SAMPLE_ORDER.map((s) => progress.bySample.get(s)?.value), finite = values.filter((v): v is number => typeof v === "number"), max = Math.max(0.8, ...finite) * 1.16;
  const width = 356, height = 76, left = 22, right = 8, top = 8, bottom = 18; const x = (i: number) => left + i * (width - left - right) / 3; const y = (v: number) => top + (1 - v / max) * (height - top - bottom);
  const connected = values.map((v, i) => v === undefined ? null : `${x(i)},${y(v)}`).filter((v): v is string => Boolean(v));
  const line = connected.length > 1 ? `<polyline points="${connected.join(" ")}" fill="none" stroke="var(--accent)" stroke-width="2" vector-effect="non-scaling-stroke" stroke-linecap="round" stroke-linejoin="round"/>` : "";
  const points = SAMPLE_ORDER.map((s, i) => { const v = values[i]; if (v === undefined) return `<circle cx="${x(i)}" cy="${height - bottom}" r="3" fill="var(--track)"/><text x="${x(i)}" y="${height - 3}" text-anchor="middle">${s}</text>`; return `${highlight.has(s) ? `<circle class="plot-ring" cx="${x(i)}" cy="${y(v)}" r="8"/>` : ""}<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="var(--accent)"/><text class="plot-value" x="${x(i)}" y="${Math.max(9, y(v) - 7)}" text-anchor="middle">${esc(formatNumber(v))}</text><text x="${x(i)}" y="${height - 3}" text-anchor="middle">${s}</text>`; }).join("");
  const sampleDots = SAMPLE_ORDER.map((s) => `<span class="sample-dot ${progress.bySample.has(s) ? "done" : s === progress.next ? "next" : ""}"><i>${progress.bySample.has(s) ? "✓" : ""}</i>${s}</span>`).join("");
  const latestMarkup = latest?.measurementType ? `<section class="latest"><div><label>${state === "PROCESSING" ? "STRUCTURED DRAFT" : "LATEST"}</label><b>Sample ${esc(clip(latest.sampleId || "—", 22))}</b><span>${esc(clip(conditionLabel(latest), 38))}</span></div><strong>${latest.value === undefined ? "—" : esc(formatNumber(latest.value))}<small>${esc(clip(latest.measurementUnit || latest.measurementType || "", 12))}</small></strong></section>` : `<section class="latest empty"><div><label>LATEST</label><b>No measurements yet</b><span>Ready for Sample ${esc(nextSample)}</span></div></section>`;
  const observation = state === "COMPLETE" ? completionMessage(observations)! : analysis.observation, stateClass = state.toLowerCase().replace(/\s+/g, "-");
  const css = BASE_CSS + `.voice{display:grid;grid-template-columns:14px minmax(0,1fr) auto;align-items:center;gap:10px;padding:9px 14px 8px;border-bottom:1px solid var(--line)}.voice-dot{width:10px;height:10px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 4px color-mix(in srgb,var(--accent) 16%,transparent)}.voice.recorded .voice-dot,.voice.complete .voice-dot{background:var(--good);box-shadow:0 0 0 4px color-mix(in srgb,var(--good) 16%,transparent)}.voice.needs-clarification .voice-dot{background:var(--bad);box-shadow:0 0 0 4px color-mix(in srgb,var(--bad) 16%,transparent)}.voice div{min-width:0}.voice b{display:block;font-size:17px;letter-spacing:.035em}.voice span{display:block;font-size:11px;color:var(--ink-2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.wave{display:flex;align-items:center;gap:2px;height:18px}.wave i{width:2px;border-radius:2px;background:var(--accent)}.wave i:nth-child(1),.wave i:nth-child(5){height:5px}.wave i:nth-child(2),.wave i:nth-child(4){height:11px}.wave i:nth-child(3){height:17px}.sample-now{display:flex;align-items:center;gap:8px;height:34px;padding:0 14px;border-bottom:1px solid var(--line)}.sample-now label{font-size:9px;font-weight:750;letter-spacing:.075em;color:var(--ink-4)}.sample-now b{font-size:13px}.sample-now span{margin-left:auto;font-size:10.5px;color:var(--ink-3)}.chart{padding:7px 14px 2px}.chart-head{display:flex;align-items:center}.chart-head b{font-size:11px;letter-spacing:.04em}.chart-head span{margin-left:auto;font-size:10px;color:var(--ink-4)}.plot{display:block;width:100%;height:76px}.plot-grid{fill:none;stroke:var(--line);vector-effect:non-scaling-stroke}.plot text{font:9px -apple-system,sans-serif;fill:var(--ink-4)}.plot .plot-value{fill:var(--ink-2);font-weight:700}.plot-ring{fill:color-mix(in srgb,var(--accent) 18%,transparent);stroke:var(--accent);vector-effect:non-scaling-stroke}.progress{display:flex;align-items:center;gap:10px;height:39px;padding:0 14px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.sample-dots{display:flex;gap:10px;flex:1}.sample-dot{display:flex;align-items:center;gap:3px;font-size:10px;color:var(--ink-4)}.sample-dot i{display:grid;place-items:center;width:13px;height:13px;border:1px solid var(--ink-4);border-radius:50%;font-style:normal;font-size:8px}.sample-dot.done{color:var(--ink-2)}.sample-dot.done i{background:var(--accent);border-color:var(--accent);color:white}.sample-dot.next{color:var(--accent)}.sample-dot.next i{border-color:var(--accent)}.progress strong{font-size:11px;white-space:nowrap}.latest{display:flex;align-items:center;gap:10px;min-height:54px;padding:8px 14px;border-bottom:1px solid var(--line)}.latest div{flex:1;min-width:0}.latest label,.ai label{display:block;font-size:9px;font-weight:760;letter-spacing:.08em;color:var(--accent)}.latest b{display:block;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.latest span{display:block;font-size:10px;color:var(--ink-4);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.latest strong{font-size:24px;white-space:nowrap}.latest strong small{font-size:10px;color:var(--ink-3);margin-left:4px}.ai{padding:7px 14px 9px;min-height:46px}.ai b{display:block;margin-top:2px;font-size:11.5px;font-weight:560;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}@media(prefers-reduced-motion:no-preference){.voice-dot{animation:arrive .28s ease-out both}}@keyframes arrive{from{transform:scale(.72)}to{transform:none}}`;
  return renderCustom({ accent: ACCENT, css, body: `<div class="lp">${header()}<section class="voice ${stateClass}"><i class="voice-dot"></i><div><b>${esc(state)}</b><span>${esc(clip(options.transcript || stateNote, 82))}</span></div>${state === "LISTENING" ? `<div class="wave" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div>` : ""}</section><section class="sample-now"><label>${state === "RECORDED" || state === "PROCESSING" ? "CURRENT" : "NEXT SAMPLE"}</label><b>${progress.complete ? "Experiment complete" : `Sample ${esc(currentSample)}`}</b><span>${progress.complete ? "4 / 4" : esc(SAMPLE_META[currentSample]?.condition || "")}</span></section><section class="chart"><div class="chart-head"><b>LIVE OD600</b><span>Latest value per sample</span></div><svg class="plot" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none"><path class="plot-grid" d="M${left} ${top}V${height - bottom}H${width - right}M${left} ${(top + height - bottom) / 2}H${width - right}"/>${line}${points}</svg></section><section class="progress"><div class="sample-dots">${sampleDots}</div><strong>${progress.count} / 4 recorded</strong></section>${latestMarkup}<section class="ai"><label>AI OBSERVATION</label><b>${esc(clip(observation, 128))}</b></section></div>`, height: 374 });
}
function nextStepCard(observations: Observation[]) { const p = experimentProgress(observations); const css = BASE_CSS + `.next-card{padding:17px 14px 20px}.next-card label{font-size:10px;font-weight:750;letter-spacing:.08em;color:var(--accent)}.step{display:grid;grid-template-columns:54px minmax(0,1fr);gap:12px;align-items:center;margin-top:12px}.step-no{width:54px;height:54px;border:2px solid var(--accent);border-radius:50%;display:grid;place-items:center;font-size:25px;color:var(--accent)}.step b{font-size:17px}.step span{display:block;margin-top:2px;color:var(--ink-3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.say{margin-top:13px;padding-top:9px;border-top:1px solid var(--line);font-size:11px;color:var(--ink-2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}`; const sample = p.next; return renderCustom({ accent: ACCENT, css, body: `<div class="lp">${header()}<section class="next-card"><label>NEXT STEP</label><div class="step"><div class="step-no">${p.complete ? "✓" : p.count + 1}</div><div><b>${p.complete ? "Experiment complete" : `Sample ${esc(sample!)}`}</b><span>${p.complete ? "All required OD600 samples are recorded." : esc(SAMPLE_META[sample!].condition)}</span></div></div><div class="say">${p.complete ? "Ask for the experiment summary." : `Say: “Sample ${esc(sample!)}, point six one.”`}</div></section></div>`, height: 205 }); }
function compareCard(a: Observation, b: Observation) { const d = b.value - a.value, absolute = Math.abs(d), higher = d === 0 ? undefined : d > 0 ? b : a, lower = d > 0 ? a : b, max = Math.max(a.value, b.value, 0.01), sentence = d === 0 ? `Samples ${a.sampleId} and ${b.sampleId} match.` : `Sample ${higher!.sampleId} is ${formatNumber(absolute)} OD600 higher.`; const css = BASE_CSS + `.compare{padding:15px 14px 18px}.compare label{font-size:10px;font-weight:750;letter-spacing:.08em;color:var(--accent)}.compare h2{font-size:18px;line-height:1.2;margin-top:5px}.bars{margin-top:13px}.bar{display:grid;grid-template-columns:68px minmax(0,1fr) 48px;align-items:center;gap:8px;height:34px;border-top:1px solid var(--line)}.bar:first-child{border-top:0}.rail{height:5px;border-radius:5px;background:var(--track);overflow:hidden}.rail i{display:block;height:100%;background:var(--accent)}.bar strong{text-align:right}.diff{margin-top:9px;padding-top:8px;border-top:1px solid var(--line);font-size:10.5px;color:var(--ink-3)}.diff span{float:right}`; const pct = lower.value ? absolute / Math.abs(lower.value) * 100 : undefined; return renderCustom({ accent: ACCENT, css, body: `<div class="lp">${header()}<section class="compare"><label>SAMPLE COMPARISON</label><h2>${esc(sentence)}</h2><div class="bars">${[a, b].map((o) => `<div class="bar"><b>Sample ${esc(clip(o.sampleId, 12))}</b><div class="rail"><i style="width:${Math.max(2, o.value / max * 100)}%"></i></div><strong>${esc(formatNumber(o.value))}</strong></div>`).join("")}</div><div class="diff">Difference · ${esc(formatNumber(absolute))} OD600${pct === undefined ? "" : `<span>${esc(pct.toFixed(1))}% vs lower</span>`}</div></section></div>`, height: 235 }); }
function readinessCard(checks: Array<{ label: string; status: string; ready: boolean }>) { const ready = checks.every((c) => c.ready), css = BASE_CSS + `.ready{padding:15px 14px 18px}.ready label{font-size:10px;font-weight:750;letter-spacing:.08em;color:${ready ? "var(--accent)" : "var(--bad)"}}.ready h2{font-size:23px;margin:5px 0 10px}.check{display:flex;align-items:center;height:30px;border-top:1px solid var(--line)}.check span{color:var(--ink-2)}.check b{margin-left:auto;font-size:10.5px}.check b.bad{color:var(--bad)}`; return renderCustom({ accent: ACCENT, css, body: `<div class="lp">${header()}<section class="ready"><label>SYSTEM READINESS</label><h2>${ready ? "Ready for the bench" : "Action needed"}</h2>${checks.map((c) => `<div class="check"><span>${esc(c.label)}</span><b class="${c.ready ? "" : "bad"}">${esc(c.status)}</b></div>`).join("")}</section></div>`, height: 105 + checks.length * 30 }); }

