server.registerTool("start_lab_session", { title: "Start lab session", description: "Start or resume the persistent hands-free session for EXP-042 without clearing saved data. Use when the user says to start the lab session or begin hands-free capture.", inputSchema: {} as any }, async () => { try { return await serialized(async () => { const db = await load(), p = experimentProgress(db.observations); db.session = { active: true, startedAt: db.session.startedAt || new Date().toISOString(), completedAt: p.complete ? db.session.completedAt || new Date().toISOString() : undefined }; await save(db); const spokenResponse = p.complete ? "Lab session ready. All four samples are complete." : `Lab session ready. Sample ${p.next}.`; return response({ sessionStarted: true, sessionActive: true, experimentId: EXPERIMENT_ID, nextSample: p.next || null, spokenResponse, progress: { recorded: p.count, total: 4 } }, dashboard(db.observations, { state: p.complete ? "COMPLETE" : "LISTENING", sessionActive: true })); }); } catch (e: any) { console.error(e); return response({ sessionStarted: false, error: "Lab session unavailable" }, errorCard("Lab session unavailable", "Local experiment storage could not be opened.")); } });
