server.registerTool("record_observation", { title: "Record observation", description: "Save one complete normalized voice observation to EXP-042. Call immediately after a complete interpretation. Exact same sample, measurement type, and value within eight seconds is deduplicated; intentional later repeats remain separate history records.", inputSchema: observationFields as any }, async (args: any) => { const draft = { ...args, inputSource: "voice" as const }; try { return await serialized(async () => { const db = await load(), now = new Date(), duplicate = [...db.observations].reverse().find((o) => normalizeSample(o.sampleId) === normalizeSample(args.sampleId) && o.measurementType.toUpperCase() === String(args.measurementType).toUpperCase() && o.value === args.value && Math.abs(now.getTime() - Date.parse(o.timestamp)) <= DUPLICATE_WINDOW_MS); if (duplicate) { const p = experimentProgress(db.observations), spokenResponse = `Already recorded, ${formatNumber(duplicate.value)}. ${p.complete ? "Experiment complete." : `Next: Sample ${p.next}.`}`; return response({ recorded: true, deduplicated: true, duplicateOf: duplicate.id, observation: duplicate, observationCount: db.observations.length, spokenResponse, progress: { recorded: p.count, total: 4, nextSample: p.next || null, complete: p.complete } }, dashboard(db.observations, { state: p.complete ? "COMPLETE" : "RECORDED", stateNote: p.complete ? "Duplicate ignored · experiment complete" : `Duplicate ignored · Listening for Sample ${p.next}`, focus: duplicate, highlight: [duplicate.sampleId], sessionActive: db.session.active })); } const observation: Observation = { ...args, id: randomUUID(), experimentId: EXPERIMENT_ID, inputSource: "voice", timestamp: args.timestamp || now.toISOString() }, priorCount = db.observations.filter((o) => normalizeSample(o.sampleId) === normalizeSample(observation.sampleId) && o.measurementType.toUpperCase() === observation.measurementType.toUpperCase()).length; db.observations.push(observation); const p = experimentProgress(db.observations); if (p.complete) db.session.completedAt = db.session.completedAt || now.toISOString(); await save(db); const spokenResponse = p.complete ? `Recorded, ${formatNumber(observation.value)}. All four samples complete.` : `Recorded, ${formatNumber(observation.value)}. Next: Sample ${p.next}.`; return response({ recorded: true, deduplicated: false, repeatedMeasurement: priorCount > 0, spokenResponse, observation, observationCount: db.observations.length, progress: { recorded: p.count, total: 4, nextSample: p.next || null, complete: p.complete }, completionObservation: p.complete ? completionMessage(db.observations) : undefined, analysis: analyze(db.observations) }, dashboard(db.observations, { state: p.complete ? "COMPLETE" : "RECORDED", stateNote: p.complete ? `Sample ${observation.sampleId} · ${readingLabel(observation)}` : `Sample ${observation.sampleId} · ${readingLabel(observation)} · Listening next: ${p.next}`, focus: observation, highlight: [observation.sampleId], sessionActive: db.session.active })); }); } catch (e: any) { console.error(e); return response({ recorded: false, draft, error: "Not recorded" }, errorCard("Measurement not recorded", "The structured draft is preserved for retry.", draft)); } });
server.registerTool("correct_last", { title: "Correct last observation", description: "Replace exactly the immediately previous EXP-042 observation after explicit correction language such as 'Actually, make that…'. Use correctionArgs returned by interpret_observation.", inputSchema: { expectedId: z.string().min(1), previousSummary: z.string().min(1).max(300), ...observationFields } as any }, async (args: any) => { try { return await serialized(async () => { const db = await load(), previous = db.observations[db.observations.length - 1]; if (!previous) return response({ corrected: false, error: "Nothing to correct" }, errorCard("Nothing to correct", `${EXPERIMENT_ID} has no saved measurements.`)); if (previous.id !== args.expectedId) return response({ corrected: false, error: "Latest observation changed", latest: previous }, errorCard("Correction not applied", "The latest record changed and remains saved.", previous)); const { expectedId, previousSummary, ...rest } = args, observation: Observation = { ...rest, id: previous.id, experimentId: EXPERIMENT_ID, inputSource: "voice", timestamp: rest.timestamp || previous.timestamp }; db.observations[db.observations.length - 1] = observation; const p = experimentProgress(db.observations); db.session.completedAt = p.complete ? db.session.completedAt || new Date().toISOString() : undefined; await save(db); const spokenResponse = `Corrected. Sample ${observation.sampleId}, ${formatNumber(observation.value)}.${p.complete ? " Experiment complete." : ` Next: Sample ${p.next}.`}`; return response({ corrected: true, spokenResponse, previous, observation, progress: { recorded: p.count, total: 4, nextSample: p.next || null, complete: p.complete }, analysis: analyze(db.observations) }, dashboard(db.observations, { state: p.complete ? "COMPLETE" : "RECORDED", stateNote: p.complete ? `Corrected · Sample ${observation.sampleId} ${formatNumber(observation.value)}` : `Corrected · Sample ${observation.sampleId} ${formatNumber(observation.value)} · Listening next: ${p.next}`, highlight: [observation.sampleId], focus: observation, sessionActive: db.session.active })); }); } catch (e: any) { console.error(e); return response({ corrected: false, error: "Correction not applied" }, errorCard("Correction not applied", "The original record remains saved.", args)); } });
server.registerTool("undo_last", { title: "Undo last observation", description: "Remove exactly the immediately previous EXP-042 observation after 'Undo that'. Use undoArgs returned by interpret_observation; session progress and the latest-value chart update immediately.", inputSchema: { expectedId: z.string().min(1), sampleId: z.string().min(1).max(100), condition: z.string().max(240).optional(), measurementType: z.string().min(1).max(100), value: z.number().finite(), measurementUnit: z.string().max(30).optional(), timestamp: z.string().optional(), rawTranscript: z.string().max(1000).optional() } as any }, async (args: any) => { try { return await serialized(async () => { const db = await load(), previous = db.observations[db.observations.length - 1]; if (!previous) return response({ undone: false, error: "Nothing to undo" }, errorCard("Nothing to undo", `${EXPERIMENT_ID} has no saved measurements.`)); if (previous.id !== args.expectedId) return response({ undone: false, error: "Latest observation changed" }, errorCard("Undo not completed", "The latest record changed and remains saved.", previous)); db.observations.pop(); const p = experimentProgress(db.observations); db.session.completedAt = p.complete ? db.session.completedAt : undefined; await save(db); const readySample = p.next || previous.sampleId, spokenResponse = `Removed. Ready for Sample ${readySample}.`; return response({ undone: true, spokenResponse, removed: previous, observationCount: db.observations.length, progress: { recorded: p.count, total: 4, nextSample: p.next || null, complete: p.complete }, analysis: analyze(db.observations) }, dashboard(db.observations, { state: p.complete ? "COMPLETE" : "LISTENING", stateNote: p.complete ? "Previous record removed · required samples remain complete" : `Ready for Sample ${readySample}`, sessionActive: db.session.active })); }); } catch (e: any) { console.error(e); return response({ undone: false, error: "Undo not completed" }, errorCard("Undo not completed", "The saved record was left unchanged.", args)); } });
server.registerTool("check_readiness", { title: "Check readiness", description: "Check VoiceOS input, parser availability, EXP-042 context, and the shared LabOS API connection. Use only for troubleshooting before a demo or lab run.", inputSchema: {} as any }, async () => { try { const db = await load(), checks = [{ label: "Voice input", status: "VoiceOS ready", ready: true }, { label: "Scientific parser", status: "Ready", ready: true }, { label: "Duplicate guard", status: "8 seconds", ready: true }, { label: "Experiment", status: EXPERIMENT_ID, ready: true }, { label: "Shared LabOS API", status: `${db.observations.length} records`, ready: true }]; return response({ ready: true, experimentId: EXPERIMENT_ID, sessionActive: db.session.active, checks }, readinessCard(checks)); } catch (e: any) { console.error(e); const checks = [{ label: "Voice input", status: "VoiceOS ready", ready: true }, { label: "Scientific parser", status: "Ready", ready: true }, { label: "Shared LabOS API", status: "Unavailable", ready: false }]; return response({ ready: false, error: "LabOS API unavailable", checks }, readinessCard(checks)); } });
